  this.housingLocationList = this.housingService.getAllHousingLocations();
}

What She wants to do :
Inject the housing service directly inside the class attribute
@Component({
//...
})
export class HomeComponent {

  housingService: HousingService = inject(HousingService);
  housingLocationList: HousingLocation[] = this.housingService.getAllHousingLocations();

  constructor() {}
}

What should I answer to her ?
What I tried :
I tried to convice her that it's a dogma and she should not think about it and just do it like that :)
What I expected :
She accept my answer
What actually resulted:
She still wants to know

